package org.sleepwell.app;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import java.time.*;
/** Explicit private SAF definition portability, separate from nap application ownership and timers. */
public final class NapProfilesDocumentsActivity extends Activity {
 private static final int DOCUMENT=690;private NapProfilesDocumentsJob job;private NapProfilesDocumentsJob.State drawn;private NapProfilesDocumentsJob.Kind selected;private boolean resumed,pickerOutstanding;private String ticket="",error="";private final Handler main=new Handler(Looper.getMainLooper());
 @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);job=NapProfilesDocumentsJob.get(this);if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::finish);if(saved!=null){error=saved.getString("error","");if(job.id.equals(saved.getString("job",""))){pickerOutstanding=saved.getBoolean("picker");ticket=saved.getString("ticket","");try{selected=NapProfilesDocumentsJob.Kind.valueOf(saved.getString("kind",""));}catch(IllegalArgumentException invalid){pickerOutstanding=false;}}else error="The document operation was interrupted. Choose the document again; no merge was resumed automatically.";}render();}
 private void render(){drawn=job.state();LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Profile definition files",this::finish);Design.space(body,14);Design.text(body,"Keep a separate copy of your profiles",23,600,Design.INK);Design.space(body,10);Design.text(body,"The JSON file contains profile names, local start times, durations and optional weekly start days. It excludes apply dates, timer IDs, active jobs and application recovery records. Choose a trusted location before exporting.",14,400,Design.MUTED);Design.space(body,14);Design.text(body,"Import only adds reviewed definitions. It never applies a profile or schedules a timer.",13,500,Design.BROWN);Design.space(body,18);
  if(drawn.phase==NapProfilesDocumentsJob.Phase.EXPORT_READY){PlanActivity.detail(body,"file","Frozen export copy",drawn.count+" profile definition"+(drawn.count==1?"":"s"),null,null);Design.text(body,"This copy reflects the profiles read when Prepare export was tapped.",12,400,Design.MUTED);}
  if(drawn.phase==NapProfilesDocumentsJob.Phase.REVIEW&&drawn.plan!=null){NapProfilesDefinitions.Plan plan=drawn.plan;Design.text(body,"Review definition merge",21,600,Design.INK);Design.space(body,8);Design.text(body,plan.additions.size()+" new · "+plan.duplicates+" exact duplicates · "+plan.conflicts.size()+" name conflicts",15,500,Design.BROWN);Design.text(body,"Duplicates are skipped. Name conflicts keep your current definition; nothing is overwritten or deleted.",13,400,Design.MUTED);for(NapProfilesDefinitions.Definition definition:plan.additions){Design.space(body,12);Design.text(body,"Add: "+definition.name,16,600,Design.INK);Design.text(body,definition.weekly?"Weekly start days · "+NapProfilesActivity.weekdays(definition.weekdays):"One-date definition",12,500,Design.MUTED);for(NapProfiles.Entry entry:definition.entries)Design.text(body,Design.clock(this,entry.minute)+" · "+PlanActivity.duration(entry.duration),13,400,Design.MUTED);}if(!plan.conflicts.isEmpty()){Design.space(body,12);Design.text(body,"Keep current for:",15,600,Design.INK);for(String name:plan.conflicts)Design.text(body,name,13,400,Design.MUTED);}if(!plan.fits()){Design.space(body,12);Design.text(body,"The whole merge would exceed 20 saved profiles. Remove definitions or choose a smaller file, then refresh this review. Nothing will be truncated.",13,500,0xffa93919);}Design.space(body,12);Design.text(body,"Current definitions: "+plan.current+" of 20",12,400,Design.MUTED);}
  if(!drawn.message.isEmpty()){Design.space(body,12);TextView status=Design.text(body,drawn.message,13,500,drawn.phase==NapProfilesDocumentsJob.Phase.ERROR||drawn.phase==NapProfilesDocumentsJob.Phase.BLOCKED?0xffa93919:Design.MUTED);status.setContentDescription("Profile document status");status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);}if(!error.isEmpty())Design.text(body,error,13,500,0xffa93919);LinearLayout footer=RecordUi.footer(body);
  if(drawn.phase==NapProfilesDocumentsJob.Phase.BLOCKED)Design.button(footer,"Retry document cleanup",true,()->{job.retryCleanup();render();});else if(drawn.busy){Design.text(footer,drawn.phase==NapProfilesDocumentsJob.Phase.MERGING?"The reviewed definition merge is committing atomically.":"Document work runs in the background. Cancelled exports may leave an empty or partial file in the selected location.",12,400,Design.MUTED);if(drawn.phase!=NapProfilesDocumentsJob.Phase.MERGING&&drawn.phase!=NapProfilesDocumentsJob.Phase.CLOSING)Design.button(footer,"Cancel document operation",false,()->{job.cancel("Stopping document work…");render();});}
  else if(drawn.phase==NapProfilesDocumentsJob.Phase.CHOOSING)Design.button(footer,"Cancel document selection",false,()->{pickerOutstanding=false;job.choiceCancelled(ticket);ticket="";render();});
  else if(drawn.phase==NapProfilesDocumentsJob.Phase.REVIEW&&drawn.plan!=null){Button merge=Design.button(footer,"Merge new definitions · keep current conflicts",true,()->{if(!hasWindowFocus())return;error="";job.merge();render();});RecordUi.enabled(merge,drawn.plan.fits()&&!drawn.plan.additions.isEmpty());Design.button(footer,"Refresh import review",false,()->{error="";job.refresh();render();});Design.button(footer,"Open saved profiles",false,()->startActivity(RecordUi.intent(this,NapProfilesActivity.class)));Design.button(footer,"Discard import review",false,()->{job.discardReview();render();});}
  else if(drawn.phase==NapProfilesDocumentsJob.Phase.EXPORT_READY){Design.button(footer,"Choose export document",true,()->choose(NapProfilesDocumentsJob.Kind.EXPORT));Design.button(footer,"Discard prepared copy",false,()->{job.discardReview();render();});}
  else{Design.button(footer,"Prepare profile export",true,()->{error="";job.prepare();render();});Design.button(footer,"Choose definition file to import",false,()->choose(NapProfilesDocumentsJob.Kind.IMPORT));}Design.space(footer,8);Design.text(footer,"Definition file limit: 64 KiB. No persistent document grants are kept.",12,400,Design.MUTED);
 }
 private void choose(NapProfilesDocumentsJob.Kind kind){if(pickerOutstanding||!hasWindowFocus())return;String own=job.choose(kind);if(own.isEmpty())return;ticket=own;selected=kind;pickerOutstanding=true;error="";render();try{Intent picker=new Intent(kind==NapProfilesDocumentsJob.Kind.IMPORT?Intent.ACTION_OPEN_DOCUMENT:Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json").addFlags(kind==NapProfilesDocumentsJob.Kind.IMPORT?Intent.FLAG_GRANT_READ_URI_PERMISSION:Intent.FLAG_GRANT_WRITE_URI_PERMISSION);if(kind==NapProfilesDocumentsJob.Kind.EXPORT)picker.putExtra(Intent.EXTRA_TITLE,"sleepwell-nap-profiles-"+LocalDate.now()+".json");startActivityForResult(picker,DOCUMENT);}catch(RuntimeException unavailable){pickerOutstanding=false;job.choiceFailed(own);ticket="";render();}}
 @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code!=DOCUMENT||!pickerOutstanding)return;pickerOutstanding=false;String own=ticket;ticket="";try{Uri uri=data==null?null:data.getData();if(result!=RESULT_OK||uri==null){job.choiceCancelled(own);render();return;}if(!job.document(own,uri)){job.choiceCancelled(own);error="This document selection expired or is unsupported. Choose a document again.";}}catch(RuntimeException invalid){job.choiceCancelled(own);error="The selected document could not be opened. Choose it again.";}render();}
 private final Runnable poll=new Runnable(){public void run(){if(!resumed)return;if(drawn!=job.state())render();main.postDelayed(this,150);}};
 @Override protected void onResume(){super.onResume();resumed=true;main.post(poll);}
 @Override protected void onPause(){resumed=false;main.removeCallbacks(poll);super.onPause();}
 @Override protected void onSaveInstanceState(Bundle saved){super.onSaveInstanceState(saved);saved.putString("job",job.id);saved.putBoolean("picker",pickerOutstanding);saved.putString("ticket",ticket);saved.putString("error",error);if(selected!=null)saved.putString("kind",selected.name());}
 @Override protected void onDestroy(){main.removeCallbacksAndMessages(null);super.onDestroy();}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
